/*common.codeList*/

		    SELECT
		        CODE,TEXT1
		    FROM
		        ICOMCOD1 
		        WHERE TYPE = #{value}

/*common.yearCodeList*/

	SELECT LEVEL AS CODE,
	       	   LEVEL || '년' AS TEXT1
	  FROM DUAL


		/* 현재 년도 이전 5개 이후 5개 조회 */

			WHERE LEVEL > TO_NUMBER(TO_CHAR(SYSDATE, 'YYYY')) - 5
			CONNECT BY LEVEL <= TO_NUMBER(TO_CHAR(SYSDATE, 'YYYY')) + 5



		/* 선택 년도 이전 5개 이후 5개 조회 */

			WHERE LEVEL > TO_NUMBER(#{SEARCH2}) - 5
			CONNECT BY LEVEL <= TO_NUMBER(#{SEARCH2}) + 5



		/* 현재 년도 이전 10개 */

			WHERE LEVEL > TO_NUMBER(TO_CHAR(SYSDATE, 'YYYY')) - 10
			CONNECT BY LEVEL <= TO_NUMBER(TO_CHAR(SYSDATE, 'YYYY'))



		/* 현재 년도 이전 2개 */

			WHERE LEVEL > TO_NUMBER(TO_CHAR(SYSDATE, 'YYYY')) - 2
			CONNECT BY LEVEL <= TO_NUMBER(TO_CHAR(SYSDATE, 'YYYY'))

/*common.masterDepartmentUserList*/
