	/*common.fileUploadFlagUpdate*/

             UPDATE ICOMATCH A  
                SET A.GABAGE_FLAG = 'Y'  
               WHERE DOC_NO = #{DOC_NO}

/*common.removeIcomatch*/

			DELETE
				FROM ICOMATCH
			WHERE DOC_NO = #{D_DOC_NO}
			AND  DOC_SEQ = #{D_DOC_SEQ}

/*common.markIcomatchAsGarbage*/

		UPDATE ICOMATCH
		   SET GABAGE_FLAG = 'Y',
		       CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'),
		       CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
		 WHERE DOC_NO = #{D_DOC_NO}
		   AND DOC_SEQ = #{D_DOC_SEQ}

