	/*common.getDocuNo*/

			SELECT DOC_TYPE||SUBSTR(YEAR,3,2)||LPAD(CUR_NO,6,0) as DOCU_NO
              FROM ICOMSQMT
            WHERE COMPANY=#{COM_CODE} 
                AND DOC_TYPE=#{DOC_TYPE}

mapper.update:
	/*common.insertDocuNo*/

			INSERT INTO ICOMSQMT(
					COMPANY
					, DOC_TYPE
					, YEAR
					, CUR_NO)
              VALUES(#{COM_CODE}
              			 , #{DOC_TYPE}
              			 , TO_CHAR(SYSDATE, 'YYYY')
              			 , 2)

	/*common.updateDocuNo*/

			UPDATE ICOMSQMT 
				  SET YEAR = TO_CHAR(SYSDATE,'YYYY')
				  		, CUR_NO = Decode(YEAR, To_Char(SysDate,'YYYY'), CUR_NO+1, 1) 
            WHERE COMPANY=#{COM_CODE} 
                AND DOC_TYPE=#{DOC_TYPE}

