/*common.selectSpecialCategUserBoolean*/

			SELECT DISTINCT STD_CATEG_ID
			FROM (
				SELECT DISTINCT STD_CATEG_ID FROM ICOMBYCA A
				WHERE A.COM_CODE =#{_st_SessionComCode}
				AND LENGTH(A.CATEG_SYS_CODE) = 8
				AND  EXISTS (
					SELECT 1 FROM ICOMCOD3 B
					WHERE B.BUYER = A.COM_CODE 
					AND B.TEXT1 = A.COM_CODE
					AND B.CODE2 = A.STD_CATEG_ID
					AND B.TYPE =  #{_st_type}
					AND B.FLAG = 'Y'
				)

			)

/*common.selectSpecialCategUserList*/

			SELECT DISTINCT STD_CATEG_ID
			FROM (
				SELECT STD_CATEG_ID FROM ICOMBYCA A, ICOMCOD3 B
				WHERE A.COM_CODE = #{_st_SessionComCode}
				AND A.COM_CODE = B.TEXT1
				AND A.STD_CATEG_ID = B.CODE2
				AND B.TYPE =#{_st_type}


		 AND B.CODE1 = #{_st_session_user_id}


				AND B.FLAG = 'Y'
				AND A.CATEG_SYS_CODE = B.TEXT2
				UNION ALL
				SELECT DISTINCT STD_CATEG_ID FROM ICOMBYCA A
				WHERE A.COM_CODE =#{_st_SessionComCode}
				AND LENGTH(A.CATEG_SYS_CODE) = 8
				AND NOT EXISTS (
					SELECT 1 FROM ICOMCOD3 B
					WHERE B.TEXT1 = A.COM_CODE
					AND B.CODE2 = A.STD_CATEG_ID
					AND B.TYPE =  #{_st_type}
					AND B.FLAG = 'Y'
				)

			)

