/*getFileUploadAtYnCnt*/
SELECT COUNT(*) AS COUNT
FROM ICOMCOD1
WHERE 	1=1
AND		TYPE = 'ATYN'
AND     CODE = #{PTYPE}

/*common.selectMenuTabInfo_v2 */ SELECT MENU.MENU_ID AS MENUID , MENU.URL AS MENU_JSP , MENU.MENU_DC AS MENU_BUTTON , NVL(MENU.ROLE_ID,'N') AS ROLEID , MENU.MENU_ORDER FROM KX_MENUINFO MENU , KX_MENUAUTH AUTH WHERE MENU.MENU_ID = AUTH.MENU_ID AND AUTH.AUTH_ID = (SELECT AUTH_ID FROM KX_USERAUTH WHERE USER_ID = #{st_user_id} AND USE_FLAG = 'Y') AND NVL(MENU.USE_FLAG, 'Y') != 'N' AND NVL(AUTH.USE_FLAG, 'Y') != 'N' AND MENU.UPPER_ID = #{st_upper_menu_id} AND MENU.ROLE_ID IS NULL
UNION ALL
SELECT MENU.MENU_ID AS MENUID , MENU.URL AS MENU_JSP , MENU.MENU_DC AS MENU_BUTTON , NVL(MENU.ROLE_ID,'N') AS ROLEID , MENU.MENU_ORDER FROM KX_MENUINFO MENU WHERE MENU.ROLE_ID IN (SELECT ROLE_ID FROM KX_USERROLE WHERE USER_ID = #{st_user_id} AND USE_FLAG = 'Y') AND NVL(MENU.USE_FLAG, 'Y') != 'N' AND MENU.UPPER_ID = #{st_upper_menu_id}
ORDER BY MENU_ORDER
